"use client";

import { useMemo, useState } from "react";

import { calculateAdditionalClicks } from "./calculator-utils";

type CalculatorBlockProps = {
  title: string;
  description?: string;
};

export function CalculatorBlock({ title, description }: CalculatorBlockProps) {
  const [monthlySearches, setMonthlySearches] = useState(10000);
  const [currentCtr, setCurrentCtr] = useState(2.1);
  const [targetCtr, setTargetCtr] = useState(3.4);

  const additionalClicks = useMemo(
    () =>
      calculateAdditionalClicks({
        monthlySearches,
        currentCtr,
        targetCtr,
      }),
    [monthlySearches, currentCtr, targetCtr],
  );

  return (
    <section aria-labelledby="calculator-heading" className="space-y-8">
      <header className="space-y-4">
        <h2 id="calculator-heading" className="text-3xl leading-tight tracking-tight text-[#EAEAEA] md:text-5xl">
          {title}
        </h2>
        {description ? <p className="max-w-4xl text-lg text-[#B0B0B0]">{description}</p> : null}
      </header>

      <form className="space-y-6 border-t border-divider pt-8" onSubmit={(event) => event.preventDefault()}>
        <div className="grid gap-6 md:grid-cols-3">
          <label className="space-y-2">
            <span className="text-sm uppercase tracking-[0.14em] text-[#EAEAEA]/75">Manedlige sok</span>
            <input
              type="number"
              min={0}
              value={monthlySearches}
              onChange={(event) => setMonthlySearches(Number(event.target.value) || 0)}
              className="w-full border-b border-divider bg-transparent py-2 text-lg text-[#EAEAEA] outline-none focus:border-[#EAEAEA]/65"
            />
          </label>

          <label className="space-y-2">
            <span className="text-sm uppercase tracking-[0.14em] text-[#EAEAEA]/75">Dagens CTR (%)</span>
            <input
              type="number"
              step="0.1"
              min={0}
              value={currentCtr}
              onChange={(event) => setCurrentCtr(Number(event.target.value) || 0)}
              className="w-full border-b border-divider bg-transparent py-2 text-lg text-[#EAEAEA] outline-none focus:border-[#EAEAEA]/65"
            />
          </label>

          <label className="space-y-2">
            <span className="text-sm uppercase tracking-[0.14em] text-[#EAEAEA]/75">Mal-CTR (%)</span>
            <input
              type="number"
              step="0.1"
              min={0}
              value={targetCtr}
              onChange={(event) => setTargetCtr(Number(event.target.value) || 0)}
              className="w-full border-b border-divider bg-transparent py-2 text-lg text-[#EAEAEA] outline-none focus:border-[#EAEAEA]/65"
            />
          </label>
        </div>
      </form>

      <p className="border-t border-divider pt-6 text-xl text-[#EAEAEA] md:text-2xl">
        Potensiell okning: {additionalClicks.toLocaleString("nb-NO")} ekstra klikk per
        maned.
      </p>
    </section>
  );
}
